add(nr=101, id="10470947324170", orig_titel="Stretch band Tunturi Power Band Extra Light Orange",
 fakta="""Stretch band Tunturi Power Band Extra Light Orange. Fördelar med Tunturi Power Stretch Gummi: Fördelarna med PowerStrength. Idealisk för att träna musklerna i ben, höfter och armar samt förbättra flexibiliteten. Flexibel, stark och hållbar. Stärker och stärker musklerna och musklerna för starka och starka muskler. "Må bättre varje dag" - det är Tuntur-mottot. Våra rötter går tillbaka till Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Sortimentet utökas och växer ständigt, med kvalitetsprodukter och bra garantier. Specifikationer: Träningsutrustningens längd: 104 cm. Längd: 104 cm. Motstånd: 2 - 15 kg. 1,5 cm - 1,5 kg - 1,5 kg Power Band levereras individuellt. Färg: Orange. Material: latex. Märke Tunturi, typ Stretchband, tagg Cykelbelysning, gummiband, Stretchband, Tunturi, Velomarket. Variant Default Title, SKU 14TUSCF027""",
 titel="Stretchband Tunturi Power Band Extra Light, 104 cm, orange",
 seo_title="Stretchband Tunturi Power Band, 104 cm",
 meta="Tunturi Power Band Extra Light är ett orange stretchband i latex, 104 cm långt och avsett för träning av musklerna i ben, höfter och armar.",
 intro="Tunturi Power Band Extra Light är ett orange stretchband i latex, 104 cm långt, för träning av musklerna i ben, höfter och armar.",
 passar=["Dig som vill träna musklerna i ben, höfter och armar med ett stretchband","Dig som vill ha ett band i latex som är 104 cm långt"],
 spec=["Längd: 104 cm","Material: latex","Färg: orange"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Effektpåståendena (\"förbättra flexibiliteten\", \"stärker musklerna\"), \"flexibel, stark och hållbar\", motståndsuppgiften och den sönderhackade raden om att bandet levereras individuellt utelämnas. Tunturis märkestext (Finland, 1922, holländskt företag) används inte.",
 att_bekrafta=["Motstånd i källan är \"2 - 15 kg\" trots att titeln säger Extra Light. Ett enskilt band kan knappast ha hela spannet. Bekräfta motståndet för just detta band.","Raden \"1,5 cm - 1,5 kg - 1,5 kg Power Band levereras individuellt\" är obegriplig (maskinöversättning) och är inte med.","Taggen \"Cykelbelysning\" verkar fel för ett stretchband.","Bredd och tjocklek saknas."])

add(nr=102, id="10507246600458", orig_titel="Yogablock TUNTURI Kork Yogablock",
 fakta="""Yogablock TUNTURI Kork Yogablock. Fördelar med ett yogablock: Mycket hållbart och miljövänligt tack vare användningen av korkmaterial. 100% naturligt, biologiskt nedbrytbart och återvinningsbart. 100% naturlig och biologiskt nedbrytbar naturfiber. 100% naturligt och biologiskt nedbrytbart. Flexibilitet och smidighet hjälper till att balansera och jämna ut yogapositioner. "Må bättre varje dag" - det är Tuntur's motto. Våra rötter går tillbaka till Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöttar dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödappar. Det är ett sortiment som ständigt utökas och förbättras, med kvalitetsprodukter och bra garantier. Specifikationer: Storlek: L 23 x B 15 x H 7,5 cm. Vikt: 720 g. Material och färg: kork. Märke Tunturi, typ Yogamattor, tagg Tunturi, Velomarket, Yoga, Yogamattor. Variant Default Title, SKU 14TUSYO050""",
 titel="Yogablock Tunturi i kork, 23 x 15 x 7,5 cm",
 seo_title="Yogablock Tunturi i kork",
 meta="Tunturi yogablock i kork för yoga, med måtten 23 x 15 x 7,5 cm (längd, bredd och höjd). Blocket väger 720 g. Material och färg är kork.",
 intro="Tunturi yogablock är ett yogablock i kork som mäter 23 x 15 x 7,5 cm och väger 720 g.",
 passar=["Dig som vill ha ett yogablock i kork","Yogaövningar där du vill ha ett block att ha till hands"],
 spec=["Storlek: 23 x 15 x 7,5 cm (L x B x H)","Vikt: 720 g","Material och färg: kork"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Miljöpåståendena (\"miljövänligt\", \"biologiskt nedbrytbart\", \"återvinningsbart\", \"100 % naturligt\"), \"mycket hållbart\" och raden om flexibilitet och smidighet (obegriplig) utelämnas. Tunturis märkestext används inte.",
 att_bekrafta=["Källan upprepar miljöpåståendet fyra gånger i olika formuleringar. Är det belagt, till exempel med intyg, kan det tas med senare.","Raden \"Flexibilitet och smidighet hjälper till att balansera och jämna ut yogapositioner\" är oklar och är inte med.","Produkttypen i butiken är \"Yogamattor\" fast det är ett block."])

add(nr=103, id="10588447572234", orig_titel="Skivstångsdyna för nacken TUNTURI Pro Barpad Deluxe",
 fakta="""Skivstångsdyna för nacken TUNTURI Pro Barpad Deluxe. Tunturi PRO BARPAD DELUXE. Gör du ofta knäböj? Eller tränar du intensivt? Glöm inte att skydda nacke och axlar. Tunturi Pro Barpad Deluxe skumrulle säkerställer ett starkt och mjukt skydd runt skivstången. Du kommer att göra dina träningspass lite roligare. Håller längre. Du kommer inte att distraheras av en tung skivstång under ditt träningspass, så du kan njuta av några fler knäböj. Gör du andra övningar efteråt? Placera snabbt dynan på stången till en annan utrustning med fästet. Pro Foam säkerställer intensiv användning: materialet är lätt att rengöra. Fördelar med Tunturi Pro Barpad Deluxe: Skyddar nacke och axlar. Passar runt all huvudutrustning. Pro Foam säkerställer intensiv användning. Hur skyddar du din nacke och axlar? Välj Tunturi Pro Barpad Deluxe och känn skillnaden under ditt träningspass. Om Tunturi: Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt expanderande och uppgraderande sortiment av högkvalitativa produkter och bra garantier. Tekniska data översikt: Mått. Vikt: 215 g. 4 cm, längd: 4 cm, längd: 4 cm. Vikt: 215 g. Vikt: 215 g. Material / Färg: Skum / Svart. Produktkod: 14TUSCL391. EAN-kod: 8717842031629. Märke Tunturi, typ Vikter och tillbehör, tagg Skivstång, Tunturi, Velomarket, Vikter och tillbehör. Variant Default Title, SKU 14TUSCL391""",
 titel="Skivstångsdyna Tunturi Pro Barpad Deluxe, skum, svart",
 seo_title="Skivstångsdyna Tunturi Pro Barpad Deluxe",
 meta="Tunturi Pro Barpad Deluxe är en skivstångsdyna i skum som skyddar nacke och axlar, till exempel vid knäböj. Vikt 215 g, färg svart, lätt att rengöra.",
 intro="Tunturi Pro Barpad Deluxe är en skivstångsdyna i skum som läggs runt skivstången för att skydda nacke och axlar, till exempel vid knäböj.",
 passar=["Dig som gör knäböj med skivstång","Dig som vill skydda nacke och axlar mot skivstången","Dig som vill kunna flytta dynan till annan utrustning med fästet"],
 spec=["Material: skum (Pro Foam), lätt att rengöra","Färg: svart","Vikt: 215 g","Har ett fäste för att flytta dynan till annan utrustning"],
 faq=[], marke=None,
 motivering="Fakta ur källan. \"Säkerställer ett starkt och mjukt skydd\", \"känn skillnaden\", \"håller längre\", \"lite roligare\" och \"passar runt all huvudutrustning\" (oklart) utelämnas. Måttraden är sönderhackad och utelämnas. Tunturis märkestext används inte.",
 att_bekrafta=["Måttraden i källan (\"Mått. ... 4 cm, längd: 4 cm, längd: 4 cm\") är trasig. Dynans längd och diameter saknas.","\"Passar runt all huvudutrustning\" är sannolikt en maskinöversättning (troligen stänger). Bekräfta vilka stångdiametrar dynan passar.","Meningen om att placera dynan på stången \"till en annan utrustning med fästet\" är oklar. Texten säger bara att det finns ett fäste. Bekräfta vad fästet är."])

add(nr=104, id="10472215937290", orig_titel="Yogablock TUNTURI Yoga Block, turkos",
 fakta="""Yogablock TUNTURI Yoga Block, turkos. Fördelar med ett yogablock: Avrundade kanter för ett behagligt grepp. Vadderad för bekvämt stöd under yogapass. Ger stödjande hjälp för en enklare yogapraktik. "Ger stödjande hjälp för Yoga Yoga Yoga Yoga Yoga hjälper till att minska risken för skador. Våra rötter sträcker sig tillbaka till Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöttar dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödappar. Det är ett sortiment som ständigt utökas och förbättras, med kvalitetsprodukter och bra garantier. Specifikationer: Vikt: 255 g. Storlek: L 23 x B 15 x H 7,5 cm. Färg: turkos. Material: EVA. Märke Tunturi, typ Yogamattor, tagg Fell, Tunturi, Velomarket, Yoga, Yogamattor. Variant Default Title, SKU 14TUSYO049""",
 titel="Yogablock Tunturi i EVA, turkos",
 seo_title="Yogablock Tunturi i EVA, turkos",
 meta="Tunturi Yoga Block är ett turkost yogablock i EVA med avrundade kanter och vadderad yta. Storlek 23 x 15 x 7,5 cm (L x B x H) och vikt 255 g.",
 intro="Tunturi Yoga Block är ett turkost yogablock i EVA med avrundade kanter. Blocket är vadderat och används vid yogapass.",
 passar=["Dig som vill ha ett vadderat block att använda vid yogapass","Dig som vill ha avrundade kanter för greppet"],
 spec=["Storlek: 23 x 15 x 7,5 cm (L x B x H)","Vikt: 255 g","Material: EVA","Färg: turkos","Avrundade kanter","Vadderad"],
 faq=[], marke=None,
 motivering="Fakta ur källan. \"Minska risken för skador\" (hälsopåstående, dessutom en trasig mening), \"behagligt grepp\", \"bekvämt stöd\" och \"enklare yogapraktik\" utelämnas. Tunturis märkestext används inte.",
 att_bekrafta=["Det andra stycket i källan är trasigt (\"Yoga Yoga Yoga Yoga Yoga\", en citationstecken som aldrig stängs) och är inte med.","Produkttypen i butiken är \"Yogamattor\" fast det är ett block."])

add(nr=105, id="10461917741322", orig_titel="Gymnastikmatta TUNTURI Fitnessmat Pro, 140cm, blå",
 fakta="""Gymnastikmatta TUNTURI Fitnessmat Pro, 140cm, blå. Gillar du att träna på gymgolvet? Ligger du på en matta under ditt träningspass? Nu kan du ta med dig din egen Tunturi Fitness Mat Pro. Det är skönt och prydligt att ha en egen matta när du gör magövningar. Du kommer att känna dig ännu mer avslappnad när du gör yogaövningar. Skaffa din egen träningsmatta, den är användbar och uppfriskande! Fördelarna med Tunturi Fitness Mat Pro: Använd din egen matta hemma eller på gymmet. Mjukt stöd under magövningar och yogaklasser tack vare det tjocka materialet. Hållbar konstruktion tack vare hög kvalitet. "Må bättre varje dag" - det är Tuntur's motto. Våra rötter finns i Finland, där två bröder öppnade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi uppnår detta genom ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödapplikationer. Sortimentet utökas och utvecklas ständigt och erbjuder produkter av hög kvalitet och utmärkta garantier. Översikt över specifikationer: Material: starkt gummi. Hållbart gummimaterial. Färg: blå. Mått: 140 cm x 60 cm x 1,5 cm Mått: 140 cm x 60 cm x 1,5 cm. Märke Tunturi, typ Yogamattor, tagg Fell, träningsmatta, Tunturi, Velomarket, Yogamattor. Varianter 14TUSFU125 (SKU 14TUSFU125), blue (SKU 14TUSFU126)""",
 titel="Gymnastikmatta Tunturi Fitnessmat Pro, 140 cm, blå",
 seo_title="Gymnastikmatta Tunturi Fitnessmat Pro",
 meta="Tunturi Fitness Mat Pro är en blå gymnastikmatta i gummi, 140 x 60 cm och 1,5 cm tjock, för magövningar och yogaövningar hemma eller på gymmet.",
 intro="Tunturi Fitness Mat Pro är en blå gymnastikmatta i gummi som mäter 140 x 60 x 1,5 cm, för användning hemma eller på gymmet.",
 passar=["Magövningar och yogaövningar","Träning på gymgolvet eller hemma","Dig som vill ha en egen matta att ta med"],
 spec=["Mått: 140 x 60 x 1,5 cm","Material: gummi","Färg: blå"],
 faq=[], marke=None,
 motivering="Fakta ur källan. \"Skönt och prydligt\", \"ännu mer avslappnad\", \"uppfriskande\", \"hållbar konstruktion tack vare hög kvalitet\" och \"mjukt stöd\" utelämnas. Tunturis märkestext används inte.",
 att_bekrafta=["Butiken har två varianter, \"14TUSFU125\" och \"blue\" (SKU 14TUSFU126). Det framgår inte om de är olika färger eller storlekar, och texten beskriver bara den blå.","Källan upprepar måttet och materialet (\"starkt gummi\" och \"hållbart gummimaterial\").","Produkttypen i butiken är \"Yogamattor\"."])

add(nr=106, id="10588447539466", orig_titel="Magträningshjul TUNTURI Pro Exercise Wheel Deluxe, med knäskydd",
 fakta="""Magträningshjul TUNTURI Pro Exercise Wheel Deluxe, med knäskydd. Fördelar med magrullehjulet: Stabil träningsrulle. Stabil stabilitet. Extra hållbar Rullen har en distinkt profil, förutom de tre ekrarna, för extra stabilitet och säkerhet. De halkfria handtagen säkerställer ett stadigt grepp. Det kan ta lite tid att lära sig rätt teknik, men när du väl har fått kläm på det kommer du inte att vilja vara utan denna träningspartner. "Må bättre varje dag" - det är Tunturis motto. Våra rötter finns i Finland, där två bröder öppnade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi uppnår detta genom ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödapplikationer. Översikt över specifikationer: Mått. Vikt: 1 kg. Material: syntetiskt. Färg: svart och grön. Märke Tunturi, typ Magträningshjul, tagg Magträningshjul, Tunturi, Velomarket. Variant Default Title, SKU 14TUSFU194""",
 titel="Magträningshjul Tunturi Pro Exercise Wheel Deluxe, med knäskydd",
 seo_title="Magträningshjul Tunturi Pro Deluxe",
 meta="Tunturi Pro Exercise Wheel Deluxe är ett magträningshjul med halkfria handtag, svart och grönt, 1 kg. Levereras med knäskydd enligt produkttiteln.",
 intro="Tunturi Pro Exercise Wheel Deluxe är ett magträningshjul med halkfria handtag, svart och grönt. Det väger 1 kg och finns med knäskydd.",
 passar=["Dig som vill träna med ett magträningshjul","Dig som vill ha halkfria handtag"],
 spec=["Vikt: 1 kg","Material: syntetiskt","Färg: svart och grön","Handtag: halkfria","Med knäskydd"],
 faq=[], marke=None,
 motivering="Fakta ur källan. \"Stabil stabilitet\", \"extra hållbar\", \"distinkt profil\" och \"tre ekrar\" (oklar översättning), \"stadigt grepp\" och \"säkerhet\" utelämnas. Raden om att lära sig tekniken utelämnas. Tunturis märkestext används inte.",
 att_bekrafta=["Knäskydd nämns bara i titeln. Beskrivningen säger inget om dem. Bekräfta att de ingår och hur de ser ut.","Källan säger \"de tre ekrarna\" och \"Stabil stabilitet\", troligen maskinöversättning. Utelämnat.","Hjulets diameter och bredd saknas (raden \"Mått.\" är tom).","Max användarvikt saknas."])

add(nr=107, id="10588447473930", orig_titel="Handledviktsmanschetter TUNTURI Handledviktsmanschetter 0,5 kg",
 fakta="""Handledviktsmanschetter TUNTURI Handledviktsmanschetter 0,5 kg. Få en ännu effektivare träning med dessa Tunturi justerbara handleds- och fotvikter! Fäst dem på anklarna eller handlederna och låt musklerna arbeta hårdare med den extra vikten. Vikterna kan enkelt fästas och tas bort med en snabbfäste. Använd dem för fitness, yoga, tennis, kampsport, skridskoåkning eller fotbollsträning. Kort sagt, det finns gott om alternativ. Vikterna sitter åt bekvämt och materialet är mjukt för optimal komfort under träning. Fördelar med Tunturi justerbar handleds-/fotvikt - 2 x 0,5 kg. - Ett billigt och enkelt sätt att öka träningsintensiteten. - Tillverkad av stark och mjuk neopren: känns bekväm. - Lätt att bära och använda var du vill. - Lämplig för ett brett utbud av sportaktiviteter: från fitness till kampsport. Lägg till en extra dimension till din träning med dessa Tunturi justerbara handleds-/fotvikter. Lägg till en extra dimension till din träning. Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och uppgraderande sortiment av högkvalitativa produkter och bra garantier. Översikt: Mått (LWH): 21 x 7 x 2,7 cm. Vikt: 2 x 0,5 kg (2 x 2,5 lbs). Storlek: En storlek. 2 per set. Kardborrefäste. Färg: grå | Svart. Material: neopren. Märke Tunturi, typ Extra vikter, tillbehör, tagg Extra vikter, tillbehör, Tunturi, Velomarket. Variant Default Title, SKU 14TUSCL239""",
 titel="Handleds- och fotvikter Tunturi 2 x 0,5 kg, neopren",
 seo_title="Handleds- och fotvikter Tunturi 2 x 0,5 kg",
 meta="Tunturi handleds- och fotvikter i neopren, 2 x 0,5 kg per set. Justerbara med kardborrefäste, i grått och svart. Mått 21 x 7 x 2,7 cm, en storlek.",
 intro="Tunturi handleds- och fotvikter är ett set om två vikter på 0,5 kg vardera i neopren, som fästs på handleder eller anklar med kardborrefäste.",
 passar=["Dig som vill träna med extra vikt på handleder eller anklar","Fitness, yoga, tennis, kampsport, skridskoåkning eller fotbollsträning","Dig som vill kunna sätta på och ta av vikterna med ett snabbfäste"],
 spec=["Vikt: 2 x 0,5 kg","Set: 2 per set","Mått (LWH): 21 x 7 x 2,7 cm","Material: neopren","Fäste: kardborrefäste","Färg: grå och svart","Storlek: en storlek"],
 faq=[], marke=None,
 motivering="Fakta ur källan. \"Effektivare träning\", \"musklerna arbetar hårdare\", \"billigt\", \"optimal komfort\" och \"extra dimension\" utelämnas. Viktangivelsen i pund utelämnas (se att bekräfta). Tunturis märkestext används inte.",
 att_bekrafta=["Källan anger \"2 x 0,5 kg (2 x 2,5 lbs)\". 0,5 kg motsvarar inte 2,5 pund. Pundvärdet är inte med.","Källan säger \"justerbara\" men beskriver bara kardborrefäste och snabbfäste. Hur vikterna justeras framgår inte.","Måttet 21 x 7 x 2,7 cm gäller sannolikt en manschett. Bekräfta.","Titeln i butiken säger \"Handledviktsmanschetter\" medan texten säger handleds- och fotvikter."])

add(nr=108, id="10470927433994", orig_titel="TUNTURI Tubing Set med grepp, lätt, gul",
 fakta="""TUNTURI Tubing Set med grepp, lätt, gul. Tunturi Tubing gymnastikset innehåller 3 olika redskap med låg vikt. Setet kan användas för att träna arm-, bröst- och axelmuskler. Till exempel övningar som biceps curl, axelpress och triceps extension. Benmusklerna kan stärkas genom att göra overhead utfall eller overhead knäböj. Ett set med stretchband är lätt att bära. 3-delat set. Vikt: ca 210 g. Färg: Gul | Svart. Material: gummi. Må bättre varje dag - Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, mer än 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och uppgraderande sortiment av högkvalitativa produkter och bra garantier. Märke Tunturi, typ Stretchband, tagg Cykelbelysning, Stretchband, Tunturi, Velomarket. Variant Default Title, SKU 14TUSFU253""",
 titel="Stretchband Tunturi Tubing Set med grepp, lätt, gul",
 seo_title="Stretchband Tunturi Tubing Set med grepp",
 meta="Tunturi Tubing Set är ett lätt, 3-delat set med stretchband och grepp i gummi, gult och svart. Används till övningar som biceps curl, axelpress och utfall.",
 intro="Tunturi Tubing Set är ett lätt, 3-delat set med stretchband och grepp i gummi. Setet väger ca 210 g och är gult och svart.",
 passar=["Övningar för arm-, bröst- och axelmuskler, till exempel biceps curl, axelpress och triceps extension","Övningar för benen, till exempel overhead utfall och overhead knäböj","Dig som vill ha ett set som är lätt att bära"],
 spec=["Innehåll: 3-delat set med 3 olika redskap","Vikt: ca 210 g","Material: gummi","Färg: gul och svart","Grepp ingår"],
 faq=[], marke=None,
 motivering="Fakta ur källan. \"Benmusklerna kan stärkas\" skrivs som övningsexempel utan effektlöfte. \"Låg vikt\" tolkas som att setet är lätt, i linje med titeln. Tunturis märkestext används inte.",
 att_bekrafta=["Källan beskriver inte vilka de tre redskapen är (till exempel band med olika motstånd) eller bandens längd och motstånd. Titeln säger \"lätt\".","Titeln säger \"med grepp\" men beskrivningen nämner inga grepp. Bekräfta att grepp ingår.","Taggen \"Cykelbelysning\" verkar fel för ett stretchband."])

add(nr=109, id="10472258535690", orig_titel="TUNTURI Sauna Smoke",
 fakta="""TUNTURI Sauna Smoke. Vill du svettas ännu mer under ditt träningspass? Ta då på dig din Tunturi-svettdräkt! Detta set uppmuntrar till svettning under din cirkelträning på gymmet, under ett träningspass eller under en löprunda i parken. Syntetmaterialet ger en fukttransporterande effekt. Svettning transporterar bort avfall och vem vet, du kanske går ner ett extra kilo. Du kan enkelt skölja av Tunturi-svettsetet efter ett träningspass, eftersom materialet är lätt att tvätta. Fördelar med Tunturi Sweat Kit - Sauna kit: Uppmuntrar till svettning under träning eller motion. Den är tillverkad av tvättbart material, så du kan snabbt få ett rent svettset efter ett träningspass. Lätt att använda och bekväm tack vare bra passform. Lätt att använda och bekväm att bära, lätt att bära, lätt att rengöra och bekväm. Beställ ditt Tunturi-svettset idag! Om Tunturi Må bättre varje dag. Det är Tunturis motto. Våra rötter går tillbaka till Finland, där två bröder startade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Det är ett sortiment som ständigt utökas och förbättras, med kvalitetsprodukter och bra garantier. Hittar du inte rätt eller har du frågor? Vårt serviceteam är redo att hjälpa dig. Vi anser att alla har rätt att njuta av bra, hälsosam träning, inklusive barn. Därför donerar vi ett belopp från varje köp du gör till Fitkids Foundation. Tillsammans ser vi till att barn med funktionsnedsättningar kan idrotta. Tekniska detaljer: Färg: grå. Material: syntetiskt. Vikt: 403 gram. Produktkod: 14TUSFU298. EAN-kod: 8717842031339. Märke Tunturi, typ Tillbehör, tagg Fell, Tillbehör, Tunturi, Velomarket. Variant Default Title, SKU 14TUSFU300""",
 titel="Svettdräkt Tunturi Sauna Smoke, syntet, grå",
 seo_title="Svettdräkt Tunturi Sauna Smoke",
 meta="Tunturi Sauna Smoke är en grå svettdräkt i syntetmaterial för användning vid träning eller motion. Materialet är tvättbart. Vikt 403 gram.",
 intro="Tunturi Sauna Smoke är en grå svettdräkt i syntetmaterial, avsedd att användas under träning eller motion. Materialet är tvättbart.",
 passar=["Dig som vill använda en svettdräkt under träningspass eller en löprunda","Dig som vill ha ett tvättbart material som går att skölja av efter träningen"],
 spec=["Material: syntetiskt, tvättbart","Färg: grå","Vikt: 403 gram"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Effekt- och hälsopåståendena (\"transporterar bort avfall\", \"du kanske går ner ett kilo\", \"uppmuntrar till svettning\", \"fukttransporterande effekt\"), säljfraser (\"Beställ ... idag\", \"bekväm tack vare bra passform\") och donationen till Fitkids Foundation utelämnas. Tunturis märkestext används inte.",
 att_bekrafta=["Källan säger inte vilka delar setet innehåller (jacka, byxor eller annat) eller vilka storlekar som finns. Det är den viktigaste luckan.","Produktkod i texten (14TUSFU298) skiljer sig från SKU (14TUSFU300).","Namnet i titeln är \"Sauna Smoke\", i texten \"Sweat Kit - Sauna kit\". Bekräfta produktnamnet.","Hälsopåståendena i källan (viktnedgång, utsöndring) bör inte användas."])

add(nr=110, id="10470888898826", orig_titel="Ball needles TUNTURI Inflation Needles (one way valve), 2 i ett paket",
 fakta="""Ball needles TUNTURI Inflation Needles (one way valve), 2 i ett paket. Dessa Tunturi-luftnålar är designade för att pumpa olika typer av bollar och passar alla bollpumpar. Ventil De krompläterade nålbaserna är utrustade med en kontrollventil. Detta säkerställer att endast luft kommer in när du pumpar bollen. Nålarna är gjorda av starkt material och levereras i ett set om 2 (blister). Fördelar med Tunturi bollpumpens luftnålar: Passar alla bollpumpar. Utrustad med kontrollventil. Pumpa dina bollar med dessa Tunturi-luftnålar. Om Tunturi: Må bättre varje dag. Det är Tunturimottot. Våra rötter finns i Finland, där två bröder startade en cykelaffär 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Det är ett sortiment som ständigt utökas och växer, med kvalitetsprodukter och bra garantier. Hittar du inte rätt eller har du frågor? Vårt serviceteam är redo att hjälpa dig. Vi anser att alla har rätt att njuta av ett bra och hälsosamt träningspass, inklusive barn. Därför donerar vi ett belopp från varje köp du gör till Fitkids Foundation. Tillsammans ser vi till att barn med funktionsnedsättningar kan idrotta. En översikt över de tekniska specifikationerna: Mått. Vikt: 90 g. Material: metall. Färg: krompläterad. Produktkod: 14TUSTE014. Märke Tunturi, typ Tillbehör, tagg Tillbehör, Tunturi, Velomarket. Variant Default Title, SKU 14TUSTE014""",
 titel="Luftnålar Tunturi med envägsventil, 2 st, krompläterade",
 seo_title="Luftnålar Tunturi med envägsventil, 2 st",
 meta="Tunturi luftnålar för att pumpa olika typer av bollar. Krompläterade nålbaser av metall med kontrollventil. Set om 2 st i blister, passar alla bollpumpar.",
 intro="Tunturi luftnålar är avsedda för att pumpa olika typer av bollar. De har krompläterade nålbaser med kontrollventil och säljs i set om två.",
 passar=["Dig som vill pumpa olika typer av bollar","Dig som vill ha nålar med kontrollventil"],
 spec=["Antal: 2 st i blister","Material: metall","Färg: krompläterad","Utrustade med kontrollventil","Passar alla bollpumpar (enligt tillverkaren)"],
 faq=[("Passar nålarna min pump?","Enligt källan passar de alla bollpumpar.")], marke=None,
 motivering="Fakta ur källan. \"Starkt material\", \"säkerställer att endast luft kommer in\" och donationen till Fitkids Foundation utelämnas. Vikten 90 g utelämnas eftersom det inte framgår om den gäller en nål eller paketet. Tunturis märkestext används inte.",
 att_bekrafta=["Det framgår inte om vikten 90 g gäller en nål eller hela paketet.","\"Passar alla bollpumpar\" är en bred uppgift. Bekräfta (olika ventiltyper och gängning).","Nålens längd och diameter saknas.","\"Envägsventil\" i titeln är en översättning av \"one way valve\"; texten kallar den kontrollventil."])

add(nr=111, id="10462190240010", orig_titel="Massage roller TUNTURI Yoga Foam Grid Roller 33cm, black",
 fakta="""Massage roller TUNTURI Yoga Foam Grid Roller 33cm, black. Koppla av dina muskler genom att massera dem med Tunturi Yoga Grid Foam Roll er. Det är ett bekvämt sätt att minska muskelömhet efter ett träningspass. Massageapparaten är gjord av ett bekvämt skummaterial så den är bekväm och praktisk att använda. Övrig information: Längd: 33,5 cm. Diameter: 14 cm. Färg: Svart. Material: EVA (skum). Märke Tunturi, typ Konditionsträning & Fitness, tagg Fell, Konditionsträning & Fitness, Massage, Tunturi, Velomarket, Yoga. Variant Default Title, SKU 14TUSYO024""",
 titel="Skumrulle Tunturi Yoga Grid, diameter 14 cm, svart",
 seo_title="Skumrulle Tunturi Yoga Grid, 14 cm",
 meta="Tunturi Yoga Grid Foam Roller är en svart skumrulle i EVA med en diameter på 14 cm. Rullens skummaterial är EVA och färgen är svart.",
 intro="Tunturi Yoga Grid Foam Roller är en svart skumrulle i EVA med en diameter på 14 cm.",
 passar=["Dig som vill ha en skumrulle i EVA att använda vid träning","Dig som vill ha en rulle med en diameter på 14 cm"],
 spec=["Diameter: 14 cm","Material: EVA (skum)","Färg: svart"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Hälsopåståendena (\"massera\", \"minska muskelömhet\", \"koppla av dina muskler\") och \"bekväm och praktisk\" utelämnas. Längden utelämnas eftersom källan motsäger sig (se att bekräfta).",
 att_bekrafta=["Titeln säger 33 cm men specifikationen säger längd 33,5 cm. Längden är därför inte med i texten. Bekräfta rätt mått.","Namnet stavas \"Yoga Foam Grid Roller\" i titeln och \"Yoga Grid Foam Roll er\" i texten.","Taggen och titeln säger \"massage\". Orden används inte i utkastet eftersom standarden inte tillåter massage- och behandlingspåståenden. David bör bekräfta om sökordet \"massagerulle\" ändå ska användas.","Produkttypen i butiken är \"Konditionsträning & Fitness\"."])

add(nr=112, id="10472281309450", orig_titel="Ben- och armvikter TUNTURI Arm/Leg Weights 1kg",
 fakta="""Ben- och armvikter TUNTURI Arm/Leg Weights 1kg. Gör ditt träningspass mer intensivt och utmanande genom att linda dessa Tunturi-vikter runt handlederna eller anklarna. Vikterna lägger extra belastning på dina muskler under sportaktiviteter som fitness, yoga, löpning eller fotboll. Ankel- och handledsvikter finns i flera modeller. Du kan börja med denna lätta version 2 x 1 kg. När det blir lättare kan du börja använda tyngre vikter. Fäst vikterna med en spännrem. Fördelar med Tunturi arm-/armvikter - 2 x 1 kg. - Vikterna har en mjuk känsla och är bekväma att bära. - Enkelt och billigt sätt att intensifiera ditt träningspass. - Lätta att bära och använda på olika platser. Beställ Tunturi arm-/armvikter och ge ditt träningspass en extra dimension! Om Tunturi: Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och uppgraderande sortiment av högkvalitativa produkter och bra garantier. Omfattande specifikationer: Mått (LWH): 13 x 4 x 34 cm. Vikt: 2 x 1 kg (2 x 1 kg). Med kardborrefäste. En storlek - 1,5 kg (1,5 lb). Set om 2 stycken. Färg: Svart | Grå. Material: nylon. Nylon Finns även i andra vikter. Produktkod: 14TUSFU118. EAN-kod: 8717842020371. Märke Tunturi, typ Extra vikter, tillbehör, tagg Extra vikter, Fell, fotledsvikt, tillbehör, Tunturi, Velomarket. Variant Default Title, SKU 14TUSFU118""",
 titel="Hand- och fotledsvikter Tunturi 2 x 1 kg, nylon",
 seo_title="Hand- och fotledsvikter Tunturi 2 x 1 kg",
 meta="Tunturi hand- och fotledsvikter i nylon, 2 x 1 kg per set, med kardborrefäste. Fästs runt handleder eller anklar. Svarta och grå, finns i fler vikter.",
 intro="Tunturi hand- och fotledsvikter är ett set om två vikter på 1 kg vardera i nylon, som fästs runt handlederna eller anklarna med kardborrefäste.",
 passar=["Dig som vill träna med extra vikt runt handleder eller anklar","Fitness, yoga, löpning eller fotboll","Dig som vill börja med en lätt version på 2 x 1 kg"],
 spec=["Vikt: 2 x 1 kg","Set: 2 stycken","Mått (LWH): 13 x 4 x 34 cm","Material: nylon","Fäste: kardborrefäste","Färg: svart och grå","Finns även i andra vikter"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Säljfraserna (\"Beställ\", \"extra dimension\", \"billigt\", \"mer intensivt och utmanande\") utelämnas. Raden \"En storlek - 1,5 kg (1,5 lb)\" utelämnas eftersom den motsäger 2 x 1 kg. Tunturis märkestext används inte.",
 att_bekrafta=["Källan har raden \"En storlek - 1,5 kg (1,5 lb)\" som motsäger 2 x 1 kg. Är 1,5 kg en kvarleva från en annan modell?","Källan säger både att vikterna fästs med spännrem och att de har kardborrefäste. Texten använder kardborrefäste (specifikationen).","Måttet 13 x 4 x 34 cm gäller sannolikt en vikt. Bekräfta.","Produkttiteln i butiken är \"Ben- och armvikter\", texten säger \"arm-/armvikter\" och handleds- och ankelvikter."])

